import {cms} from '@/cms'
import {Author, BlogPost} from '@/schema'
import {Query} from 'alinea'

export async function authorPage(path: string) {
  const author = await cms.get({
    type: Author,
    path,
    select: {id: Query.id, name: Query.title, bio: Author.bio}
  })
  const posts = await cms.find({
    type: BlogPost,
    // Single link: has, multiple links: includes
    filter: {author: {has: {_entry: author.id}}},
    select: {title: Query.title, url: Query.url},
    orderBy: {desc: BlogPost.publishDate}
  })
  return {author, posts}
}
